<script setup>import{onMounted,reactive,ref}from'vue';import api from '../../../services/api';import FormErrors from '../../../components/ui/FormErrors.vue';const roles=ref([]),permissions=ref([]),error=ref(null),busy=ref(false),editing=ref(null);const form=reactive({name:'',slug:'',description:'',permissions:[]});async function load(){const[r,p]=await Promise.all([api.get('/v1/platform/roles'),api.get('/v1/platform/permissions')]);roles.value=r.data.data;permissions.value=p.data.data}onMounted(async()=>{try{await load()}catch(e){error.value=e}});function select(role=null){editing.value=role;Object.assign(form,{name:role?.name||'',slug:role?.slug||'',description:role?.description||'',permissions:role?.permissions?.map(p=>p.name)||[]})}function slug(){if(!editing.value)form.slug=form.name.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}async function save(){busy.value=true;error.value=null;try{if(editing.value)await api.put('/v1/platform/roles/'+editing.value.id,form);else await api.post('/v1/platform/roles',form);await load();select()}catch(e){error.value=e}finally{busy.value=false}}</script><template><div><header class="page-header"><div><RouterLink class="back-link" :to="{name:'admin.users'}">Back to System Users</RouterLink><h1 class="mt-3">Roles &amp; Permissions</h1><p>Create reusable roles and control access to platform administration functions.</p></div><button class="btn" @click="select()">+ Add Role</button></header><FormErrors :error="error"/><div class="grid gap-6 xl:grid-cols-[1fr_1.2fr]"><section class="admin-card"><div class="card-heading"><h2>Platform roles</h2></div><button v-for="role in roles" :key="role.id" class="mb-3 w-full rounded-xl border p-4 text-left hover:border-teal-500" @click="select(role)"><span class="flex justify-between gap-3"><strong>{{role.name}}</strong><span class="badge badge-green">{{role.users_count}} users</span></span><span class="mt-1 block text-sm text-slate-500">{{role.description||'No description'}}</span><span class="mt-2 block text-xs text-slate-500">{{role.permissions.length}} permissions</span></button></section><form class="admin-card" @submit.prevent="save"><div class="card-heading"><h2>{{editing?'Edit role':'Create role'}}</h2></div><div class="form-grid"><label class="field">Role name<input v-model="form.name" required @blur="slug"></label><label class="field">Slug<input v-model="form.slug" required :disabled="editing?.is_system"></label><label class="field md:col-span-2">Description<textarea v-model="form.description" rows="2"></textarea></label></div><h3 class="section-title">System permissions</h3><div class="mt-4 grid gap-3 sm:grid-cols-2"><label v-for="permission in permissions" :key="permission.id" class="feature-option rounded-lg border p-3"><input v-model="form.permissions" type="checkbox" :value="permission.name">{{permission.label}}</label></div><div class="mt-6 flex justify-end gap-3"><button type="button" class="btn-secondary" @click="select()">Clear</button><button class="btn" :disabled="busy">{{busy?'Saving...':editing?'Save Role':'Create Role'}}</button></div></form></div></div></template>
